-- ============================================================================
-- BED 106 Business Analytics - Checkpoint 1 (Preliminary Period)
-- Retail & Sales Analytics: Customer Segmentation & Purchase Behavior Analysis
--
-- Dataset : Online Retail Data Set (UCI Machine Learning Repository /
--           Kaggle mirror: jihyeseo/online-retail-data-set-from-uci-ml-repo)
-- License : CC BY 4.0
-- Scope   : Real transactions from the FIRST 300 invoices of the source file
--           (2010-12-01 to 2010-12-03), a manageable classroom-sized slice of
--           the full 541,909-row dataset, cleaned and normalized into 4 tables.
--
-- Run this whole file in phpMyAdmin (XAMPP) -> Import, or paste it into the
-- SQL tab and click Go. It creates the database, schema, loads the data, and
-- runs the 8 required queries for Task 1.4 (results appear as separate result
-- sets in phpMyAdmin -- screenshot each one).
-- ============================================================================

DROP DATABASE IF EXISTS retail_customer_analytics;
CREATE DATABASE retail_customer_analytics CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE retail_customer_analytics;

-- ----------------------------------------------------------------------------
-- SCHEMA
-- ----------------------------------------------------------------------------

CREATE TABLE customers (
    customer_id     INT PRIMARY KEY,
    country         VARCHAR(50) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE products (
    stock_code      VARCHAR(20) PRIMARY KEY,
    description     VARCHAR(150) NOT NULL,
    unit_price      DECIMAL(10,2) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE invoices (
    invoice_no      VARCHAR(10) PRIMARY KEY,
    customer_id     INT NULL,
    invoice_date    DATETIME NOT NULL,
    is_cancelled    TINYINT(1) NOT NULL DEFAULT 0,
    CONSTRAINT fk_invoices_customer
        FOREIGN KEY (customer_id) REFERENCES customers(customer_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE invoice_items (
    invoice_item_id INT AUTO_INCREMENT PRIMARY KEY,
    invoice_no      VARCHAR(10) NOT NULL,
    stock_code      VARCHAR(20) NOT NULL,
    quantity        INT NOT NULL,
    unit_price      DECIMAL(10,2) NOT NULL,
    CONSTRAINT fk_items_invoice
        FOREIGN KEY (invoice_no) REFERENCES invoices(invoice_no),
    CONSTRAINT fk_items_product
        FOREIGN KEY (stock_code) REFERENCES products(stock_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

