-- ============================================================================
-- TASK 1.4 -- SQL QUERY REPORT  (8 required queries)
-- ============================================================================

-- ----------------------------------------------------------------------------
-- 1. BASIC DATA RETRIEVAL (SELECT + WHERE + ORDER BY)
-- ----------------------------------------------------------------------------

-- Query 1: High-value order lines (line total >= 15 pounds), most expensive first.
SELECT ii.invoice_no,
       p.description,
       ii.quantity,
       ii.unit_price,
       ROUND(ii.quantity * ii.unit_price, 2) AS line_total
FROM invoice_items ii
JOIN products p ON p.stock_code = ii.stock_code
WHERE ii.quantity * ii.unit_price >= 15
ORDER BY line_total DESC;

-- Query 2: Customers based in Germany or France, grouped alphabetically by country.
SELECT customer_id, country
FROM customers
WHERE country IN ('Germany', 'France')
ORDER BY country, customer_id;

-- ----------------------------------------------------------------------------
-- 2. AGGREGATE ANALYSIS (GROUP BY + Aggregate Functions)
-- ----------------------------------------------------------------------------

-- Query 3: Total revenue and number of completed orders generated by each country.
SELECT c.country,
       COUNT(DISTINCT i.invoice_no) AS order_count,
       ROUND(SUM(ii.quantity * ii.unit_price), 2) AS total_revenue
FROM invoices i
JOIN customers c ON c.customer_id = i.customer_id
JOIN invoice_items ii ON ii.invoice_no = i.invoice_no
WHERE i.is_cancelled = 0
GROUP BY c.country
ORDER BY total_revenue DESC;

-- Query 4: Top-selling products by total quantity sold, average price, and revenue.
SELECT p.description,
       SUM(ii.quantity) AS total_qty_sold,
       ROUND(AVG(ii.unit_price), 2) AS avg_price,
       ROUND(SUM(ii.quantity * ii.unit_price), 2) AS total_revenue
FROM invoice_items ii
JOIN products p ON p.stock_code = ii.stock_code
JOIN invoices i ON i.invoice_no = ii.invoice_no
WHERE i.is_cancelled = 0
GROUP BY p.stock_code
ORDER BY total_revenue DESC
LIMIT 10;

-- ----------------------------------------------------------------------------
-- 3. MULTI-TABLE JOINS
-- ----------------------------------------------------------------------------

-- Query 5: Top 10 completed invoices by total value, with customer and country.
SELECT i.invoice_no,
       c.customer_id,
       c.country,
       i.invoice_date,
       ROUND(SUM(ii.quantity * ii.unit_price), 2) AS invoice_total
FROM invoices i
JOIN customers c ON c.customer_id = i.customer_id
JOIN invoice_items ii ON ii.invoice_no = i.invoice_no
WHERE i.is_cancelled = 0
GROUP BY i.invoice_no
ORDER BY invoice_total DESC
LIMIT 10;

-- Query 6: Full order detail (customer + product) for a single invoice, 3-way join.
SELECT i.invoice_no,
       c.customer_id,
       c.country,
       p.description,
       ii.quantity,
       ii.unit_price,
       ROUND(ii.quantity * ii.unit_price, 2) AS line_total
FROM invoices i
JOIN customers c ON c.customer_id = i.customer_id
JOIN invoice_items ii ON ii.invoice_no = i.invoice_no
JOIN products p ON p.stock_code = ii.stock_code
WHERE i.invoice_no = '536365'
ORDER BY line_total DESC;

-- ----------------------------------------------------------------------------
-- 4. BUSINESS-RELEVANT INSIGHTS (answer the key business questions)
-- ----------------------------------------------------------------------------

-- Query 7: Customer segmentation by total spend and order frequency (RFM-style).
--   High-Value Customer   : total spend >= 300
--   Repeat Customer       : 3 or more separate orders
--   One-Time/Low-Value    : everyone else
SELECT c.customer_id,
       c.country,
       COUNT(DISTINCT i.invoice_no) AS order_count,
       ROUND(SUM(ii.quantity * ii.unit_price), 2) AS total_spend,
       CASE
           WHEN SUM(ii.quantity * ii.unit_price) >= 300 THEN 'High-Value Customer'
           WHEN COUNT(DISTINCT i.invoice_no) >= 3        THEN 'Repeat Customer'
           ELSE 'One-Time / Low-Value Customer'
       END AS customer_segment
FROM customers c
JOIN invoices i ON i.customer_id = c.customer_id AND i.is_cancelled = 0
JOIN invoice_items ii ON ii.invoice_no = i.invoice_no
GROUP BY c.customer_id
ORDER BY total_spend DESC;

-- Query 8: Products most frequently cancelled/returned (data-driven quality flag).
SELECT p.description,
       COUNT(*) AS cancellation_lines,
       SUM(ABS(ii.quantity)) AS units_returned
FROM invoice_items ii
JOIN invoices i ON i.invoice_no = ii.invoice_no
JOIN products p ON p.stock_code = ii.stock_code
WHERE i.is_cancelled = 1
GROUP BY p.stock_code
ORDER BY units_returned DESC;
